// engine/config.ts — 由 config.json + keys.json 生成 engine.yaml（CLIProxyAPI v8 格式）
//
// 安全底线：api-keys 为空时引擎完全不鉴权（实测），所以没有可用 key 就拒绝生成。
import YAML from 'yaml';
import { DshModelError } from '../errors.js';
import { L } from '../i18n.js';
import { activeKeys } from '../keys.js';
import { readText, writeInPlace } from '../util/fs.js';
import { loadCompatUpstreams, renderCompat } from './compat.js';
import { ensureMgmt } from './mgmt.js';
const HEADER = [
    '# GENERATED BY dsh-model — DO NOT EDIT. Run `dsh-model setup` to regenerate.',
    '# 由 dsh-model 生成，请勿手改。需要重新生成请执行 `dsh-model setup`。',
].join('\n');
export function renderEngineConfig(ctx, config, keys, port = config.port, compat = [], mgmtSecret = '') {
    const apiKeys = activeKeys(keys).map((k) => k.key);
    if (apiKeys.length === 0) {
        throw new DshModelError('no_api_keys', L('没有可用的 key，拒绝生成引擎配置（空 key 列表会让引擎不做鉴权）', 'No active keys; refusing to write engine config (an empty key list disables engine auth)'));
    }
    const doc = {
        'config-version': 8,
        server: { host: '127.0.0.1', port },
        // 管理接口：有密钥才打开（只监听本机、不开网页控制台），给 dsh-model 自己做登录 / 开关 / 用量统计（设计 §14.4）
        management: { 'allow-remote': false, 'secret-key': mgmtSecret, 'disable-control-panel': true },
        access: { 'api-keys': apiKeys },
        oauth: { 'auth-dir': ctx.paths.auth },
        routing: { strategy: 'fill-first' },
        ...(config.proxy ? { requests: { 'proxy-url': config.proxy } } : {}),
        ...(compat.length ? { 'api-keys': { 'openai-compatibility': renderCompat(compat) } } : {}),
        observability: {
            logs: { 'logging-to-file': true, 'logs-max-total-size-mb': 50, 'request-log': false },
            // 用量记录给守护进程统计 key / 来源 / 模型的速度与稳定性；它每 5 秒取一次，保留 10 分钟足够兜住停顿
            ...(mgmtSecret ? { usage: { 'usage-statistics-enabled': true, 'redis-usage-queue-retention-seconds': 600 } } : {}),
        },
    };
    return `${HEADER}\n${YAML.stringify(doc)}`;
}
/** 写 engine.yaml；内容没变就不动（避免引擎无谓的热重载）。返回是否写了 */
export async function writeEngineConfig(ctx, config, keys) {
    const mgmt = await ensureMgmt(ctx);
    const text = renderEngineConfig(ctx, config, keys, config.port, await loadCompatUpstreams(ctx), mgmt.secret);
    if ((await readText(ctx.paths.engineYaml)) === text)
        return false;
    // 原地写：保留 inode，让引擎（含 Linux）的 fsnotify 能收到变化并热重载，谁写都行、不用重启
    await writeInPlace(ctx.paths.engineYaml, text, { owner: ctx.owner });
    return true;
}
